extern "C" int sprintf(char *, const char *, ...);
extern "C" char *strcpy(char *, const char *);

class stringx
{
  char *chars;
  void *my_buf;
public:
  static int npos;
  stringx(const char *, int = -1);
  stringx(const stringx &);
  ~stringx();
  int find(const char *) const;
  const char *c_str() const { return chars; }
};

class entity
{
  char released_fields[132];
  stringx parsedName;
public:
  stringx get_parsed_name() { return parsedName; }
};

class player_info
{
  entity *accomplishments[20];
  int numAccomplishments;
public:
  void AddAccomplishment(entity *);
  int GetNumAccomplishments() const { return numAccomplishments; }
  bool HasAccomplishment(const entity *) const;
};

class ScoringManager
{
public:
  void AddGap(int);
};

class SurfBoardObjectClass
{
  char released_fields[1120];
  int in_air;
public:
  bool InAir() const { return in_air != 0; }
};

class kellyslater_controller
{
  char released_board_prefix[1120];
  int board_in_air;
  char released_score_gap[3220];
  ScoringManager my_scoreManager;
  char released_jump_gap[2552];
  entity *jumped_entities[3];
  int num_jumped__entities;
public:
  SurfBoardObjectClass &get_board_controller()
    { return *reinterpret_cast<SurfBoardObjectClass *>(this); }
  ScoringManager &get_my_scoreManager() { return my_scoreManager; }
  int GetNumJumpedEntities() const { return num_jumped__entities; }
  entity *GetJumpedEntity(const int idx) { return jumped_entities[idx]; }
};

enum EventType { SS_LAST = 105 };

class IGOFrontEnd
{
public:
  void Print(stringx, EventType = SS_LAST);
};

class FEManager
{
public:
  IGOFrontEnd *IGO;
};

extern player_info current_player_info;
extern stringx ksGlobalTextArray[];
extern FEManager frontendmanager;

class beach
{
public:
  bool CheckEnvGoal(kellyslater_controller *, stringx, int, int, int, int, int);
};

bool beach::CheckEnvGoal(kellyslater_controller *ksctrl, 
                         stringx entity_name, 
                         int num_to_jump, 
                         int gap_to_add, 
                         int gt_partially_done,
                         int gt_done,
                         int goal_num)
{
	bool            gotOne = false;
	char            display_text[100]; // for printing out messages to the IGO
	ScoringManager &scoreManager = ksctrl->get_my_scoreManager();

	if(!ksctrl->get_board_controller().InAir())
	{
		// Go through the whole list of jumped entities and if we find one 
		// that is the type we're looking for but isn't in the 
		// accomplishments list, add it.
		for (int i = 0; i < ksctrl->GetNumJumpedEntities(); i++)
		{
			entity *	jumped = ksctrl->GetJumpedEntity(i);

			if ((jumped != NULL) && (jumped->get_parsed_name().find (entity_name.c_str()) != stringx::npos ))
			{
				if (!current_player_info.HasAccomplishment(jumped))
				{
					current_player_info.AddAccomplishment(jumped);
					scoreManager.AddGap(gap_to_add);

					if (current_player_info.GetNumAccomplishments()  < num_to_jump)
					{
						// Load display_text with something like "1 of 3 tubers", except 
						// appropriate to the current state of things by using the global
						// text array (this also allows for localization)

						if (num_to_jump > 1)
							sprintf(display_text, ksGlobalTextArray[gt_partially_done].c_str(), current_player_info.GetNumAccomplishments(), num_to_jump);
						else
							strcpy(display_text, ksGlobalTextArray[gt_partially_done].c_str());

						frontendmanager.IGO->Print(display_text);
					}
					else if (current_player_info.GetNumAccomplishments() == num_to_jump)
						gotOne = true;
				}
			}
		}
	}
	return gotOne;
}
